def binarySearch(nums, target):
    # Bug: infinite loop - doesn't narrow search space
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        # Bug: missing else-if
        left = mid + 1
    return -1
